<?php
declare(strict_types=1);
function current_user():?array{return $_SESSION['user']??null;}
function require_login():array{$user=current_user();if(!$user)redirect('/?page=login');$stmt=db()->prepare('SELECT id,name,username,role,active FROM users WHERE id=?');$stmt->execute([$user['id']]);$fresh=$stmt->fetch();if(!$fresh||!(int)$fresh['active']){$_SESSION=[];session_destroy();redirect('/?page=login');}$_SESSION['user']=$fresh;return $fresh;}
function require_roles(string ...$roles):array{$user=require_login();if(!in_array($user['role'],$roles,true)){http_response_code(403);exit('Você não tem permissão para esta ação.');}return $user;}
function login_user(string $username,string $password):bool{$pdo=db();$ip=substr((string)($_SERVER['REMOTE_ADDR']??'local'),0,45);$limit=$pdo->prepare("SELECT COUNT(*) FROM login_attempts WHERE ip=? AND kind='login' AND success=0 AND created_at>=NOW()-INTERVAL 15 MINUTE");$limit->execute([$ip]);if((int)$limit->fetchColumn()>=5)return false;$stmt=$pdo->prepare('SELECT id,name,username,password_hash,role,active FROM users WHERE username=? LIMIT 1');$stmt->execute([$username]);$row=$stmt->fetch();$ok=$row&&(int)$row['active']===1&&password_verify($password,$row['password_hash']);$log=$pdo->prepare("INSERT INTO login_attempts(ip,username,kind,success) VALUES(?,?,'login',?)");$log->execute([$ip,$username,$ok?1:0]);if(!$ok)return false;session_regenerate_id(true);$_SESSION['user']=['id'=>$row['id'],'name'=>$row['name'],'username'=>$row['username'],'role'=>$row['role'],'active'=>$row['active']];return true;}
